<script setup lang="ts">import{computed}from'vue';import{useRoute,useRouter}from'vue-router';import{companies}from'../stores/career';import signals from'../data/signals.json';import{fitScore,timingFor,visaFit}from'../services/recommendations';const route=useRoute(),router=useRouter(),company=computed(()=>companies.find(x=>x.id===route.params.id));const signal=computed(()=>company.value?(signals as Record<string,{period:string;summary:string;sourceUrl:string}>)[company.value.name]:undefined);function track(){if(company.value)router.push({path:'/tracker',query:{company:company.value.name}})}</script>
<template><main v-if="company"><RouterLink to="/companies">← 返回公司目录</RouterLink><header class="detail-hero card"><div class="eyebrow">{{company.priority}} · 匹配分 {{fitScore(company)}}</div><h1>{{company.name}}</h1><p>{{company.industry}} · {{company.cities.join(' · ')}}</p></header><div class="detail-grid"><section class="card panel"><h2>为什么推荐</h2><p>{{company.fitReason}}</p></section><section class="card panel"><h2>推荐岗位</h2><div class="tags"><span v-for="r in company.recommendedRoles" class="pill">{{r}}</span></div></section><section class="card panel"><h2>发展方向</h2><p>{{company.focusAreas.join('、')}}</p></section><section class="card panel"><h2>最新公开信号</h2><template v-if="signal"><b>{{signal.period}}</b><p>{{signal.summary}}</p><a :href="signal.sourceUrl" target="_blank">查看来源 ↗</a></template><p v-else>尚未录入逐条核实的近期公告。申请前请检查官方 Careers 与 Newsroom 最近90天信息。</p></section><section class="card panel"><h2>工作权判断</h2><b>{{visaFit(company)[0]}}</b><p>{{visaFit(company)[1]}}</p></section><section class="card panel"><h2>投递时间</h2><b>{{timingFor(company)[0]}}</b><p>{{timingFor(company)[1]}}</p></section></div><div class="actions"><a class="button primary" :href="company.careerUrl" target="_blank">打开官方 Careers ↗</a><button class="button" @click="track">加入投递研究</button></div></main><main v-else><h1>未找到公司</h1><RouterLink to="/companies">返回目录</RouterLink></main></template>
